/**
 * @fileoverview Package place reads a spreadsheet cell as a place: a
 * country, by its ISO 3166-1 code or by a name in English, Spanish,
 * Portuguese, French, German or Italian, or a first-level region of one of
 * the countries the table holds regions for, by its ISO 3166-2 code, that
 * code without its country, or a name.
 *
 * The table is data/places.json, generated by core/scripts/geo from Natural
 * Earth. Its lookup is built the first time a cell is read.
 */

import table from './data/places.json' with { type: 'json' };

/** A country as places.json holds it. */
interface Country {
  code: string;
  a3?: string;
  names: string[];
}

/** A region as places.json holds it, with its ISO 3166-2 code. */
interface Region {
  code: string;
  names: string[];
}

/** How a column of places reads: as countries, or as one country's regions. */
export type Reading =
  | { level: 'country' }
  | { level: 'region'; country: string };

const COUNTRIES: readonly Country[] = table.countries;
const REGIONS: Readonly<Record<string, readonly Region[]>> = table.regions;

/** The countries whose regions a reading reads, by ISO 3166-1 alpha-2. */
export const REGION_COUNTRIES: readonly string[] = Object.keys(REGIONS);

// What normalisation takes off: the marks NFKD splits from their letters,
// every run of characters that is no letter or digit, and a leading "the".
const MARKS = /\p{M}/gu;
const NOT_WORD = /[^\p{L}\p{N}]+/gu;
const THE = /^the /;

/**
 * placeKey is the one form a place's name is compared in: NFKD with its
 * marks dropped, lower case, every run of other characters one space, and a
 * leading "the" dropped. So `Côte d'Ivoire` and `COTE D IVOIRE` are one key.
 */
export function placeKey(v: string): string {
  const bare = v.normalize('NFKD').replace(MARKS, '').toLowerCase();
  return bare.replace(NOT_WORD, ' ').trim().replace(THE, '');
}

/** What a key two places share maps to: neither, so it is never a guess. */
const SHARED = '';

/**
 * keyed maps every key of `places`' codes and names to its code; a key two
 * of them share maps to SHARED.
 */
function keyed(
  places: ReadonlyArray<{ code: string; names: string[] }>,
  codes: (code: string) => string[],
): Map<string, string> {
  const out = new Map<string, string>();
  for (const p of places) {
    for (const name of [...codes(p.code), ...p.names]) {
      const key = placeKey(name);
      const had = out.get(key);
      out.set(key, had === undefined || had === p.code ? p.code : SHARED);
    }
  }
  return out;
}

/** Each reading's lookup, built the first time it reads a cell. */
const lookups = new Map<string, Map<string, string>>();

/** lookup is the map from key to code that `reading` reads with. */
function lookup(reading: Reading): Map<string, string> {
  const name = reading.level === 'country' ? '' : reading.country;
  let found = lookups.get(name);
  if (found !== undefined) return found;
  if (reading.level === 'country') {
    const a3 = new Map(COUNTRIES.map((c) => [c.code, c.a3 ?? c.code]));
    found = keyed(COUNTRIES, (code) => [code, a3.get(code)!]);
  } else {
    // A region reads by its code, and by that code without its country.
    const bare = (code: string) => [
      code,
      code.slice(reading.country.length + 1),
    ];
    found = keyed(REGIONS[reading.country] ?? [], bare);
  }
  lookups.set(name, found);
  return found;
}

/**
 * readPlace is the ISO code of the place `v` names under `reading`: ISO
 * 3166-1 alpha-2 for a country, ISO 3166-2 for a region. It is undefined
 * when `v` names none, or names more than one.
 */
export function readPlace(v: string, reading: Reading): string | undefined {
  const code = lookup(reading).get(placeKey(v));
  return code === SHARED ? undefined : code;
}
